if (app.IsPwa()) {
    auto observedId = ResolvePwaId(window, appData, pwaHelper);
    if (!observedId || *observedId != app.pwaAppId) continue;
} else if (!NameOrPathMatches(app, appData)) {
    continue;
}

auto pwaId = ResolvePwaId(windowAumid);
if (!pwaId) { LogUnresolvedPwa(windowAumid, processPath); return std::nullopt; }
return pwaId;
